  ('d5bdf857-ff69-4e67-83e5-af044083b494', $$Natuurkunde$$, $$HAVO$$, $$Wereldrecord blobspringen$$, $$HAVO Natuurkunde 2019-I$$),
  ('5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$Natuurkunde$$, $$HAVO$$, $$Kookstenen$$, $$HAVO Natuurkunde 2019-I$$),
  ('b65159b0-3965-4803-9b12-a2bedcb08fa2', $$Natuurkunde$$, $$HAVO$$, $$Oude horloges$$, $$HAVO Natuurkunde 2019-I$$),
