insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('7e63b5b0-9c84-4759-98cf-be1bdde1f047', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$figuur 1 — infographic energieverbruik marineschip vs huishoudens$$,
   $$natuurkunde-havo-2019-i-walstroom-context1.png$$, 497,
   $$De Nederlandse marine heeft een artikel uitgebracht over de energievoorziening van marineschepen. In dit artikel wordt de vergelijking gemaakt tussen het elektrisch energieverbruik van een marineschip en dat van huishoudens. Zie figuur 1. Eén huishouden gebruikt per jaar gemiddeld 3,5 ∙ 10³ kWh.

Uit deze gegevens volgt dat het elektrisch vermogen van het marineschip 1,2 ∙ 10⁶ W is.

figuur 1: infographic ''Energie verbruik'' met een schip en drie huisjes; 1 schip komt overeen met ca. 3.000 huishoudens.$$, 'inline'),
  ('ac7706f1-1cd4-40b0-9fb5-9609ae149cc0', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$figuur 2 — rendementsschema dieselmotor (35%) en generator (80%) met pijlen I, II, III$$,
   $$natuurkunde-havo-2019-i-walstroom-context2.png$$, 497,
   $$Op het marineschip wordt elektriciteit opgewekt met een dieselmotor. Deze motor verbrandt stookolie en drijft een generator aan. Het rendement van de dieselmotor is 35%. Het rendement van de generator is 80%. In figuur 2 is dit met pijlen op schaal weergegeven.

figuur 2: schema met pijlen op schaal; pijl I gaat de dieselmotor in (η = 35%), vanuit de dieselmotor gaat pijl II omlaag en een bredere pijl naar de generator (η = 80%), vanuit de generator gaat pijl III naar rechts.

Iedere pijl staat voor een bepaalde soort energie. Deze figuur is ook op de uitwerkbijlage weergegeven.$$, 'inline'),
  ('a8999f5a-d54b-49e8-8dbd-8f8b3b9e6210', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$generator wekt elektrisch vermogen op van 1,2·10⁶ W$$,
   $$natuurkunde-havo-2019-i-walstroom-context3.png$$, 497,
   $$De generator van het schip wekt een elektrisch vermogen op van 1,2∙10⁶ W.$$, 'inline'),
  ('9b41215e-0e59-432d-8ce9-a9c5055a0e14', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$36 parallelle kabels, 440 V, 1,2·10⁶ W vermogen$$,
   $$natuurkunde-havo-2019-i-walstroom-context4.png$$, 497,
   $$In de haven kan een schip aangesloten worden op de elektriciteit aan land, de zogenaamde walstroom. De dieselmotor hoeft dan niet te draaien. Voor een marineschip worden 36 identieke kabels parallel aangesloten tussen land en schip. Er wordt een spanning gebruikt van 440 V om 1,2∙10⁶ W aan elektrisch vermogen te leveren.$$, 'inline'),
  ('69e3face-6200-49ce-a6da-1eb623441901', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$figuur 3 — hoogspanningskabel 6,6 kV, 13 m lang, koper, doorsnede 25 cm²$$,
   $$natuurkunde-havo-2019-i-walstroom-context5.png$$, 497,
   $$De Nederlandse marine gebruikt tegenwoordig een nieuwe methode om schepen aan te sluiten op het elektriciteitsnet in de haven. Ze gebruiken daarbij een spanning van 6,6 kV en nog maar één hoogspanningskabel. Deze kabel vervangt alle 36 kabels die eerst nodig waren. Zie figuur 3.

figuur 3: foto van de aansluiting van de hoogspanningskabel tussen een gebouw aan de wal en het marineschip.

De hoogspanningskabel is 13 m lang. De kabel is gemaakt van koper. De kabel heeft een doorsnede met een oppervlakte van 25 cm².$$, 'inline'),
  ('c74213db-8295-4185-838e-e5a559b1b50e', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$nieuwe kabel: minder koper, lager energieverlies, groter weerstand, gelijk vermogen$$,
   $$natuurkunde-havo-2019-i-walstroom-context6.png$$, 497,
   $$De nieuwe methode van aansluiten heeft veel voordelen. Het schip kan door minder mensen in kortere tijd aangesloten worden op het elektriciteitsnet aan wal. Voor de nieuwe kabel is veel minder koper nodig dan voor de 36 oorspronkelijke kabels. Bovendien is het energieverlies in de kabel lager.
De dunnere hoogspanningskabel is even lang, maar heeft een veel grotere weerstand dan de oorspronkelijke 36 kabels parallel samen. Het elektrisch vermogen van het schip is gelijk gebleven.$$, 'inline'),
  ('a779d275-b029-4595-8268-5b27d7ffa862', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$uitwerkbijlage vraag 2 — schema pijlen I, II, III met tabel te omcirkelen energiesoorten$$,
   $$natuurkunde-havo-2019-i-walstroom-uitwerkbijlage-vraag2.png$$, 497,
   $$Uitwerkbijlage vraag 2: hetzelfde schema als figuur 2 (pijl I naar de dieselmotor, pijl II vanuit de dieselmotor, pijl III vanuit de generator), gevolgd door een tabel met voor pijl I, pijl II en pijl III de te omcirkelen energiesoorten: kinetische energie, chemische energie, elektrische energie, warmte, zwaarte-energie.$$, 'uitwerkbijlage'),
  ('5f6dc33a-ce07-46c7-a421-e67862c3ff41', 'c023f127-53f2-42e4-bb2b-04c268fe73bf', $$uitwerkbijlage vraag 6 — zinnen met te omcirkelen alternatief over geleidbaarheid en stroomsterkte$$,
   $$natuurkunde-havo-2019-i-walstroom-uitwerkbijlage-vraag6.png$$, 497,
   $$Uitwerkbijlage vraag 6: ''De geleidbaarheid van de 6,6 kV kabel is veel groter dan / ongeveer even groot als / veel kleiner dan de geleidbaarheid van de 36 oude 440 V kabels samen.'' en ''De stroomsterkte door de 6,6 kV kabel is veel groter dan / ongeveer even groot als / veel kleiner dan de stroomsterkte door de 36 oude 440 V kabels samen.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('f7350a63-cb1b-4e69-bc85-0ec87414a51e', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$figuur 1 — fotomontage van de recordpoging blobspringen$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context1.png$$, 497,
   $$In juni 2011 werd het wereldrecord blobspringen verbeterd door Reto Zimmerli. Zie de fotomontage in figuur 1. Voor deze afbeelding zijn diverse na elkaar gemaakte foto's van de recordpoging samengevoegd tot één beeld. Zes van deze foto's zijn ook apart weergegeven op de uitwerkbijlage. Links sprong een groep van drie personen tegelijk van een hoge toren. Ze landden op het uiteinde van een met lucht gevulde zak op het water, de blob. Hierdoor werd Zimmerli, die diep weggezakt in het andere uiteinde van de blob lag te wachten, de lucht in geschoten.

figuur 1: fotomontage van de recordpoging: links springt de groep van drie personen van een hoge toren en landt op het ene uiteinde van de blob; rechts wordt Zimmerli, die aan het andere uiteinde van de blob lag, de lucht in geschoten.$$, 'inline'),
  ('4e121898-65db-451d-aa08-b4612576dd91', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$figuur 2 — (h,t)-diagram van de groep en Zimmerli$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context2.png$$, 497,
   $$Van de beweging van de deelnemers aan deze recordpoging is met behulp van een videometing een (h,t)-diagram gemaakt. Zie figuur 2. De hoogte is gemeten ten opzichte van het wateroppervlak.

figuur 2: (h,t)-diagram (hoogte t.o.v. wateroppervlak in m, 0-18) tegen de tijd in s (0-6); de curve van de 3 personen daalt vanaf ongeveer 10 m naar 0 m bij t ≈ 1,3 s, de curve van Zimmerli stijgt vanaf 0 m bij t ≈ 1,3 s tot een top van ongeveer 16,5 m rond t ≈ 3,3 s en daalt daarna weer naar 0 m bij t ≈ 5,2 s.$$, 'inline'),
  ('737018a1-20f6-451b-ba9e-5d80423f0c42', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$drie personen raken de blob op t = 1,27 s; figuur 2 ook op uitwerkbijlage$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context3.png$$, 497,
   $$Tijdens de val ondervindt de groep van drie personen weerstand. De drie personen die op de blob vallen, raken de blob op t = 1,27 s. Figuur 2 is ook op de uitwerkbijlage weergegeven.$$, 'inline'),
  ('1c984f79-7717-43ed-8fb4-ae7f9a7fcd6c', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$drukgolf van groep naar Zimmerli: vertrek t = 1,27 s, aankomst t = 1,34 s$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context4.png$$, 497,
   $$Als de drie personen op t = 1,27 s de blob raken, begint er in de blob een drukgolf te bewegen van de groep naar Zimmerli. Op t = 1,34 s komt de drukgolf bij Zimmerli aan.$$, 'inline'),
  ('8ff6b9c2-00cc-4730-850c-b73d47a84c25', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$gemiddelde versnelling Zimmerli 1,78·10² m s⁻², massa 80 kg$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context5.png$$, 497,
   $$Uit de videometing volgt dat Zimmerli tijdens de lancering door de blob een gemiddelde versnelling omhoog heeft ondergaan van 1,78∙10² m s⁻². Zimmerli heeft een massa van 80 kg.$$, 'inline'),
  ('c34d49f5-b261-412c-b1bc-fd4b321c9329', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$foto 3 op de uitwerkbijlage: Zimmerli op weg naar het hoogste punt$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context6.png$$, 497,
   $$Foto 3 op de uitwerkbijlage toont Zimmerli op weg naar het hoogste punt.$$, 'inline'),
  ('21a33b6b-c8c0-4860-a434-db95e57c2388', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$groep massa 300 kg viel 9,9 m omlaag; Zimmerli massa 80 kg$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context7.png$$, 497,
   $$De groep van drie personen met een gezamenlijke massa van 300 kg viel over een afstand van 9,9 m omlaag. Zimmerli heeft een massa van 80 kg.$$, 'inline'),
  ('4bf67db0-b2a7-49f2-b61c-668ed7ad1200', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$luchtweerstand niet verwaarloosbaar; drie mogelijke verklaringen op uitwerkbijlage$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-context8.png$$, 497,
   $$De luchtweerstand is niet verwaarloosbaar, waardoor Zimmerli bij deze recordpoging minder hoog kwam dan de maximale hoogte die hij zou kunnen bereiken. Op de uitwerkbijlage staan nog drie mogelijke verklaringen voor het niet bereiken van de maximale hoogte.$$, 'inline'),
  ('066fc3bc-9a36-4c9e-a8c7-8688dd27612b', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$uitwerkbijlage — zes foto's van de recordpoging met bijschriften$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-uitwerkbijlage-vraag10.png$$, 497,
   $$Uitwerkbijlage: zes foto's van de recordpoging met bijschriften: 1 De groep springt van de duikplank. 2 De groep landt links op de blob. 3 Zimmerli is rechts door de blob gelanceerd. 4 Zimmerli bereikt het hoogste punt. 5 Zimmerli valt richting het water. 6 Zimmerli raakt het water.$$, 'uitwerkbijlage'),
  ('8b002f52-9f75-40aa-b897-7a4774f04db8', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$uitwerkbijlage vraag 7 — figuur 2 herhaald met ruimte voor de bepaling$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-uitwerkbijlage-vraag7.png$$, 497,
   $$Uitwerkbijlage vraag 7: figuur 2 ((h,t)-diagram van de 3 personen en Zimmerli) herhaald, met ruimte voor de bepaling van de snelheid waarmee de groep de blob raakt.$$, 'uitwerkbijlage'),
  ('d3a113c2-19d0-4bc5-9d40-78100cd87388', 'd5bdf857-ff69-4e67-83e5-af044083b494', $$uitwerkbijlage vraag 12 — tabel met drie mogelijke verklaringen, juist/onjuist$$,
   $$natuurkunde-havo-2019-i-wereldrecord-blobspringen-uitwerkbijlage-vraag12.png$$, 497,
   $$Uitwerkbijlage vraag 12: tabel met drie mogelijke verklaringen (''De blob neemt energie op.'', ''De zwaartekracht remt Zimmerli af.'', ''Zimmerli schiet schuin omhoog weg.'') en kolommen juist/onjuist.$$, 'uitwerkbijlage'),
  ('333e914a-a699-49ef-8708-a2365b99441c', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$figuur 1, 2 — kookstenen in eikenhouten pot; archeologen meten steentemperatuur met infrarood-thermometer$$,
   $$natuurkunde-havo-2019-i-kookstenen-context1.png$$, 497,
   $$In de prehistorie kookten mensen water met behulp van kookstenen. Deze stenen werden in hete as opgewarmd en daarna in een eikenhouten pot met koud water gedaan. Na enige tijd begon het water te koken. Zie figuur 1.

Archeologen van de Universiteit Leiden experimenteerden met deze methode. De stenen die zij gebruikten waren van graniet. Met behulp van een infrarood-thermometer kon de temperatuur van zo'n steen in de as bepaald worden omdat een hete steen infraroodstraling uitzendt. Zie figuur 2.

figuur 1: foto van een eikenhouten bak met stenen en water in de buitenlucht.
figuur 2: twee foto's; links archeologen die met stokjes in de aarde/as werken, rechts een hand die met een infrarood-thermometer een temperatuurmeting doet in de as.$$, 'inline'),
  ('cdcd68e5-5cac-4ae6-9923-4ba2cd571e32', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$temperatuur van de steen is 384 °C$$,
   $$natuurkunde-havo-2019-i-kookstenen-context2.png$$, 497,
   $$De temperatuur van de steen is 384 °C.$$, 'inline'),
  ('2e700d05-ce60-4877-8a6f-9d8c991c7174', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$figuur 3 — tabel dichtheid, warmtegeleidingscoëfficiënt, soortelijke warmte van graniet, basalt, eikenhout$$,
   $$natuurkunde-havo-2019-i-kookstenen-context3.png$$, 497,
   $$In figuur 3 staat een tabel met een aantal stofeigenschappen van materialen die in deze opgave een rol spelen.

figuur 3: tabel met kolommen dichtheid (10³ kg m⁻³), warmtegeleidingscoëfficiënt (W m⁻¹ K⁻¹) en soortelijke warmte (10³ J kg⁻¹ K⁻¹):
graniet: 2,7 / 3,5 / 0,82
basalt: 3,0 / 1 / 0,88
eikenhout: 0,78 / 0,4 / 2,4$$, 'inline'),
  ('d9fb0a99-d380-4619-834c-f22cafe1233a', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$steen graniet 2,3 kg, begintemp 384 °C; water van 18 °C naar 100 °C$$,
   $$natuurkunde-havo-2019-i-kookstenen-context4.png$$, 497,
   $$De steen van graniet heeft een massa van 2,3 kg en een begintemperatuur van 384 °C. De steen koelt af in het water. Door de vrijgekomen energie wordt het water verwarmd van 18 °C tot het kookpunt van 100 °C. Verwaarloos het opwarmen van de houten pot en warmteverlies naar de omgeving.$$, 'inline'),
  ('321276da-f036-4863-a326-83ca38f8a9ba', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$experiment herhaald met kooksteen van basalt, zelfde begintemperatuur$$,
   $$natuurkunde-havo-2019-i-kookstenen-context5.png$$, 497,
   $$Het experiment wordt herhaald onder dezelfde omstandigheden. Nu wordt een kooksteen van basalt gebruikt in plaats van de kooksteen van graniet. De begintemperatuur van beide kookstenen is even hoog.$$, 'inline'),
  ('a3c55433-0f9b-4b85-a78e-0194436b854f', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$eikenhouten pot verliest in werkelijkheid warmte aan de omgeving$$,
   $$natuurkunde-havo-2019-i-kookstenen-context6.png$$, 497,
   $$De eikenhouten pot met water verliest in werkelijkheid wel warmte aan de omgeving.$$, 'inline'),
  ('6d196040-6e83-4a79-beb4-6263d5314b80', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$opwarmtijd varieert; tabel met vijf situaties op de uitwerkbijlage$$,
   $$natuurkunde-havo-2019-i-kookstenen-context7.png$$, 497,
   $$De opwarmtijd van een bepaalde hoeveelheid water zal variëren onder verschillende omstandigheden. Op de uitwerkbijlage staat een tabel met vijf verschillende situaties waarin steeds één omstandigheid verschilt. Alle overige omstandigheden blijven gelijk.$$, 'inline'),
  ('0caab951-29c2-4850-9888-a6ed4698fa62', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$warmtestroom grootst bij kokend water; wandoppervlak 1·10³ cm², dikte 3 cm, buitenlucht 20 °C$$,
   $$natuurkunde-havo-2019-i-kookstenen-context8.png$$, 497,
   $$De warmtestroom door de wand van de eikenhouten pot is het grootst als het water aan de kook is. De archeologen hebben de oppervlakte van de wand van de pot geschat op 1 ∙ 10³ cm² en de dikte van de wand op 3 cm. De temperatuur van de buitenlucht is 20 °C.$$, 'inline'),
  ('d1562b3f-e669-432a-9952-6662c3594231', '5b2e16d3-cacc-4964-9d2f-951e92a5e991', $$uitwerkbijlage vraag 16 — tabel met vijf situaties, kolommen opwarmtijd langer/korter$$,
   $$natuurkunde-havo-2019-i-kookstenen-uitwerkbijlage-vraag16.png$$, 497,
   $$Uitwerkbijlage vraag 16: tabel met kolom ''situatie'' (vijf omstandigheden: groter oppervlak bij gelijke massa, hogere begintemperatuur, deksel op de pot, bredere en minder diepe pot met dezelfde hoeveelheid water, bevroren bodem) en kolommen ''opwarmtijd water wordt langer'' / ''opwarmtijd water wordt korter'' om aan te kruisen.$$, 'uitwerkbijlage'),
  ('25991845-3caf-434a-b735-c32f7d679f3c', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$figuur 1, 2 — de 'Accutron', het eerste elektronische horloge met stemvork$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context1.png$$, 497,
   $$In de jaren '60 en '70 kwamen er horloges op de markt waarin nieuwe technische ontwikkelingen werden toegepast. Eén van de ontwikkelingen was gericht op de nauwkeurigheid van de horloges. Horloges werkten tot dan toe mechanisch; de wijzers werden daarbij aangedreven door een veer. Een horlogemaker kwam in 1960 met de 'Accutron', het eerste elektronische horloge. Het horloge maakte gebruik van een stemvork. Zie figuren 1 en 2. De harmonische trilling van de stemvork werd gebruikt om de draaisnelheid van de wijzers te regelen.

figuur 1: foto van het horloge 'Accutron' met open kast, met het uurwerk zichtbaar.
figuur 2: foto van de losse stemvork met bijbehorende spoelen van het horloge.$$, 'inline'),
  ('bd3fc8fe-e496-43bd-aba2-6591fd377a2f', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$oscillogram stemvork op uitwerkbijlage, 1 hokje = 1,0 ms; hoorbaar gebied 20 Hz–20 kHz$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context2.png$$, 497,
   $$Op de uitwerkbijlage zie je een oscillogram van de stemvork. Hierin is de uitwijking uitgezet tegen de tijd. Eén hokje staat voor 1,0 ms. De mens hoort frequenties tussen 20 Hz en 20 kHz.$$, 'inline'),
  ('7bed5126-0fdb-43e8-9cc3-1f62dc7722e1', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$NASA wilde techniek gebruiken in ruimtevaart; stemvork als massa-veersysteem met veerconstante C$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context3.png$$, 497,
   $$De NASA wilde deze techniek ook gebruiken voor klokken in de ruimtevaart. Een stemvork kun je beschouwen als een massa-veersysteem met een bepaalde veerconstante C. Voor de nauwkeurigheid van de klok is het belangrijk dat de trillingstijd van de stemvork heel constant is.$$, 'inline'),
  ('38f68d6e-5c2d-468b-ab31-45a5ee272049', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$figuur 3 — wijzerplaat geverfd met promethium-147 en zinksulfide, aangeduid met ℗; Pm-147 zendt alleen β-straling uit$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context4.png$$, 497,
   $$Een andere nieuwe ontwikkeling had te maken met de afleesbaarheid van horloges. De wijzers en getallen werden geverfd met een mengsel van promethium-147 en zinksulfide zodat deze oplichtten in het donker. Op de wijzerplaat werd dit aangegeven met een ℗. Zie figuur 3.

figuur 3: foto van een chronograafhorloge met wijzerplaat.

Promethium-147 (Pm-147) is een radioactieve stof die alleen β-straling uitzendt.$$, 'inline'),
  ('4fa80b18-0c80-464f-a8df-79e3322d56fe', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$wijzers zenden ook röntgenstraling uit; ioniserend vermogen β groter dan röntgen, toch groter risico röntgen$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context5.png$$, 497,
   $$De wijzers zenden ook röntgenstraling uit. Deze is niet afkomstig van het promethium-147. De behuizing van het horloge is gemaakt van ijzer. Het ioniserend vermogen van β-straling is groter dan dat van röntgenstraling. Toch blijkt de röntgenstraling voor (de pols van) de drager van het horloge een groter risico dan de β-straling.$$, 'inline'),
  ('283f4fb5-4eeb-48c2-9e96-8562a4167ed1', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$röntgenstraling 0,05 MeV per foton; dikte ijzer achterzijde 1,47 mm$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context6.png$$, 497,
   $$De röntgenstraling heeft een energie van 0,05 MeV per foton. De dikte van het ijzer aan de achterzijde van het horloge is 1,47 mm.$$, 'inline'),
  ('92b1fda2-10e0-4267-bd6a-2e54b3b5fde6', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$pols 75 gram, 25 röntgenfotonen/s per jaar, stralingsweegfactor 1, dosislimiet 50·10⁻³ Sv$$,
   $$natuurkunde-havo-2019-i-oude-horloges-context7.png$$, 497,
   $$Het deel van de pols dat wordt bestraald door de röntgenstraling heeft een massa van 75 gram en ontvangt gedurende een jaar gemiddeld 25 röntgenfotonen per seconde. De stralingsweegfactor voor röntgenstraling is gelijk aan 1. De jaarlijkse dosislimiet voor ledematen bedraagt 50 ∙ 10⁻³ Sv.$$, 'inline'),
  ('38b65b12-891a-4dc5-b7bd-a54f2f377a28', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$uitwerkbijlage vraag 19 — oscillogram van de stemvork, 1 hokje = 1,0 ms$$,
   $$natuurkunde-havo-2019-i-oude-horloges-uitwerkbijlage-vraag19.png$$, 497,
   $$Uitwerkbijlage vraag 19: oscillogram van de stemvork (uitwijking tegen tijd), een periodiek golfje van ongeveer 3,5 herhalingen; 1 hokje op de tijdas staat voor 1,0 ms.$$, 'uitwerkbijlage'),
  ('cea74874-3d9d-424f-920f-7175d67af967', 'b65159b0-3965-4803-9b12-a2bedcb08fa2', $$uitwerkbijlage vraag 23 — tabel percentages doorgelaten straling en toelichtingsregels$$,
   $$natuurkunde-havo-2019-i-oude-horloges-uitwerkbijlage-vraag23.png$$, 497,
   $$Uitwerkbijlage vraag 23: tabel met te omcirkelen percentages (0 tot 20%, 20 tot 40%, 40 tot 60%, 60 tot 80%, 80 tot 100%) en regels voor de toelichting.$$, 'uitwerkbijlage'),
  ('f5300376-c1b7-446d-bd36-b8923a55b55b', 'b7eb0ae4-46c4-42fd-aea9-4c1f7a83648c', $$figuur 1 — ringvormig ruimtestation Elysium met draaias S$$,
   $$natuurkunde-havo-2019-i-elysium-context1.png$$, 497,
   $$In de film 'Elysium' uit 2013 is een enorm, ringvormig ruimtestation te zien waarvan de rand bewoond wordt. Zie figuur 1. In deze opgave worden twee waarnemingen uit de film op natuurkundige juistheid gecontroleerd.

figuur 1: illustratie van het ringvormige ruimtestation Elysium boven de aarde, met de draaias S aangegeven.

Het ruimtestation 'Elysium' draait in een cirkelbaan rond de aarde. Als de hoogte van Elysium boven het aardoppervlak bekend is, is het mogelijk om de baansnelheid van Elysium rond de aarde uit te rekenen.$$, 'inline'),
  ('d2d1ea5d-a1fe-4895-b8db-c640240cc1e7', 'b7eb0ae4-46c4-42fd-aea9-4c1f7a83648c', $$formule r³/T² = GM/4π² voor cirkelbaan; geostationaire baan op 36·10³ km hoogte$$,
   $$natuurkunde-havo-2019-i-elysium-context2.png$$, 497,
   $$In de film lijkt het erop dat Elysium zich voortdurend boven hetzelfde punt van de aarde bevindt. In dat geval zou Elysium zich in de geostationaire baan moeten bevinden.

r³/T² = GM/4π²

Voor de cirkelvormige baan van een object om een planeet geldt:
Hierin is:
− r de straal van de cirkelbaan;
− T de omlooptijd;
− G de gravitatieconstante;
− M de massa van de planeet.

De geostationaire baan bevindt zich op een hoogte van 36 ∙ 10³ km boven het aardoppervlak.$$, 'inline'),
  ('94208be3-4214-44c8-a537-653f342c5f38', 'b7eb0ae4-46c4-42fd-aea9-4c1f7a83648c', $$figuur 2 — hoek α van Elysium en de maan vanaf de aarde; diameter Elysium 64·10³ m, maan 3,5·10⁶ m$$,
   $$natuurkunde-havo-2019-i-elysium-context3.png$$, 497,
   $$Om te controleren of Elysium in de geostationaire baan zit is een andere waarneming uit de film te gebruiken. In de film lijkt Elysium vanaf de aarde gezien even groot als de maan. Dat betekent dat je Elysium en de maan allebei onder dezelfde hoek α vanaf de aarde ziet. Zie figuur 2. Deze figuur is niet op schaal. De diameter van het ruimtestation is 64 ∙ 10³ m. De maan heeft een diameter van 3,5 ∙ 10⁶ m.

figuur 2: twee schematische tekeningen vanaf de aarde gezien, elk met dezelfde hoek α; boven: de aarde met Elysium op afstand ''geostationaire hoogte?'' en diameter 64∙10³ m; onder: de aarde met de maan op afstand 3,8∙10⁸ m en diameter 3,5∙10⁶ m.$$, 'inline'),
  ('9382b553-adf9-449f-91b1-d3959419f8aa', 'b7eb0ae4-46c4-42fd-aea9-4c1f7a83648c', $$in baan om de aarde ben je gewichtloos; Elysium draait als een wiel om as S, normaalkracht werkt als middelpuntzoekende kracht$$,
   $$natuurkunde-havo-2019-i-elysium-context4.png$$, 497,
   $$In een baan om de aarde ervaar je geen normaalkracht; je bent gewichtloos. Elysium draait als een wiel met constante baansnelheid om zijn as S. Zie figuur 1. Een bewoner in de ring ervaart hierdoor wel een normaalkracht waardoor het lijkt alsof hij op het aardoppervlak staat. Deze normaalkracht werkt als middelpuntzoekende kracht.$$, 'inline'),
  ('45f8b043-3a8f-4359-af3b-97382abc094c', 'b7eb0ae4-46c4-42fd-aea9-4c1f7a83648c', $$benodigde baansnelheid 5,8·10² m/s; Elysium draait 3,0° in 3,2 s; straal 32 km$$,
   $$natuurkunde-havo-2019-i-elysium-context5.png$$, 497,
   $$In de film ervaart een bewoner van de ring van Elysium dezelfde normaalkracht als hij op het aardoppervlak zou ervaren. Om dat effect te bereiken zou de rand van Elysium met een baansnelheid van 5,8∙10² m s⁻¹ om S moeten draaien.
In de film is te zien dat Elysium om zijn eigen as draait. In 3,2 s draait het station over een hoek van 3,0 graden. Na 360 graden draaien heeft Elysium een volledige omwenteling afgelegd. De straal van Elysium is 32 km.$$, 'inline');

